TP.register({id:"lp8-g1",lp:8,grade:"1",mode:"curriculum",checks:7,nextGrade:"2nd grade",build(E){const F=E.F;const TREE="tree",FLOWER="purpleFlower",SPROUT="sprout",LEAF="leaf",BIRD="bluebird",SNAIL="snail",BEE="bee",DUCK="duck",EGG="egg",RAIN="rain",DROP="drop",SUN="sun",BOOT="boot",UMBRELLA="umbrella",CARROT="carrot",BOOK="books",PACK="pack",EAR="ear";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",SEEDC="#C9875A",STEM="#7FC08A",LEAF_A="#A8D49A",LEAF_B="#BFE3A8",LEAF_INK="#4E7A46",SKY="#C8E9F8",GRASS="#CFE8A8",GRASS_D="#B2D986",GRASS_L1="#A3C777",GRASS_L2="#8EBB64",SOIL="#C08A5E",SOIL_D="#A8724E",SUNC="#FBD873";function seedShape(x,y,s,c,noFace){return window.TP_SEEDIMG(x,y,s)}const seedSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.1)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a seed">${seedShape(w*.5,w*.626,w*.91,c)}</svg>`;const FIRST_ROW="Our class planted a row of beans. We did it last week. Every morning I check the soil. I want to see the row. Has anything come up yet? For six days I saw nothing. There was only dark dirt. Then it rained all night. This morning I found two leaves. They were tiny and green. They were pushing up through the mud. My teacher let me take a stick. I put it in the row. It goes beside the sprout. Now we can watch it grow. Tomorrow I will measure it. I will use a string.";const MINA="Mina found one last seed at the bottom of the seed packet. But the garden rows were already full, and there was no room left. So Mina got an old cup and filled it with soil. She planted the seed on the windowsill. Every day she gave it one spoonful of water. For a long time nothing happened. Then one morning a thin green loop pushed up out of the soil. It stood up straight and tall. Mina carried the cup to school, because she wanted to show her class.";const NEEDS="A seed is a tiny plant that has its own lunch packed around it. The seed stays dry and still until three things reach it. First it needs water. The coat around the seed is hard, and water makes it soften. Next it needs air. That is why good soil is never packed down too tight, so that air can get through. Last it needs warmth. When water, air, and warmth have all arrived, the coat splits open, and a small white root pushes down into the soil.";const WORMS="After a hard rain you will often see worms up on the sidewalk. For a long time people thought the worms came up because their tunnels had filled with water. Scientists now think something else is going on. A worm breathes through its skin, and it can do that just fine in wet soil. What a worm cannot do is travel far underground. On a wet morning the whole surface is damp, and that is the one time a worm can crawl a long way to a new patch of garden. So a rainy morning is moving day for worms.";const GREENHOUSE="The greenhouse is warm even on a cold spring morning. Its roof is made of glass, so the sunlight gets in but the wind stays out. Long tables hold tray after tray of small green sprouts. A hose runs along the floor to water them. When a sprout is strong enough, someone carries it outside and plants it in the garden row.";const WORDS=["chick","pond","bloom","well","vine","right","sprout","barn","planted","sunshine","garden","frean"];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}const skyBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;const plainBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const grassBand=(w,top,h)=>`<path d="M8 ${top} Q${w*.3} ${top-14} ${w*.56} ${top-2} T${w-8} ${top-6} V${top+h} H8 Z" fill="${GRASS}"/><path d="M8 ${top} Q${w*.3} ${top-14} ${w*.56} ${top-2} T${w-8} ${top-6}" fill="none" stroke="${GRASS_L1}" stroke-width="3.2" stroke-linecap="round"/><path d="M8 ${top+28} Q${w*.36} ${top+12} ${w*.64} ${top+26} T${w-8} ${top+22} V${top+h} H8 Z" fill="${GRASS_D}"/><path d="M8 ${top+28} Q${w*.36} ${top+12} ${w*.64} ${top+26} T${w-8} ${top+22}" fill="none" stroke="${GRASS_L2}" stroke-width="3.2" stroke-linecap="round"/>`;const soilRow=(x0,x1,top,h)=>`<rect x="${x0}" y="${top}" width="${x1-x0}" height="${h}" rx="12" fill="${SOIL}" stroke="${INK}" stroke-width="3"/><path d="M${x0+16} ${top+12} q22 -7 44 0 t44 0 t44 0 t44 0 t44 0" fill="none" stroke="${SOIL_D}" stroke-width="3" stroke-linecap="round" opacity=".8"/>`;function rowFig(n){const w=620,h=190,base=108;let b=skyBox(w,h)+grassBand(w,base,h-base-11);b+=soilRow(26,w-26,base+28,44);for(let i=0;i<n;i++)b+=seedShape(26+(i+.5)*(w-52)/n,base+50,44);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A row of soil in the garden with ${n} seeds planted along it">${b}</svg>`}function seedGrid(n,per){const cell=70,rows=Math.ceil(n/per),w=per*cell+20,h=rows*cell+24;let b=plainBox(w,h);const cols=[SEEDC,"#D7A86E"];for(let i=0;i<n;i++)b+=seedShape(10+i%per*cell+cell/2,16+Math.floor(i/per)*cell+cell/2,54,cols[Math.floor(i/per)%2]);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,620)}" role="img" aria-label="${n} seeds">${b}</svg>`}function unitFig(){const u=52,y1=64,y2=166,W=460,H=264;let s=`<svg viewBox="0 0 ${W} ${H}" width="440" role="img" aria-label="A leafy vine above six blocks laid end to end, and a garden hose above four blocks laid end to end. Every block is the same size.">`;s+=plainBox(W,H-2);s+=`<path d="M40 ${y1-10} h${6*u}" stroke="${STEM}" stroke-width="10" stroke-linecap="round" fill="none"/>`;for(let i=0;i<3;i++){const x=76+i*104;s+=`<path d="M${x} ${y1-12} C${x+2} ${y1-36} ${x+24} ${y1-40} ${x+30} ${y1-28} C${x+24} ${y1-14} ${x+10} ${y1-10} ${x} ${y1-12} Z" fill="${LEAF_A}" stroke="${LEAF_INK}" stroke-width="2.6" stroke-linejoin="round"/>`}for(let i=0;i<6;i++)s+=`<rect x="${40+i*u}" y="${y1}" width="${u}" height="28" fill="${SUNC}" stroke="${INK}" stroke-width="2.5"/>`;s+=`<text x="40" y="${y1+52}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)">vine</text>`;s+=`<path d="M40 ${y2-10} h${4*u}" stroke="#4E8CA8" stroke-width="12" stroke-linecap="round" fill="none"/>`;for(let i=0;i<4;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="28" fill="${SUNC}" stroke="${INK}" stroke-width="2.5"/>`;s+=`<text x="40" y="${y2+52}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)">hose</text>`;s+=`<text x="${W/2}" y="${H-16}" font-size="19" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}function gardenChart(){return F.table(["What we take","What it is for"],[[`${seedSvg(34)} a bean seed`,"it goes into the row two fingers deep"],[`${ic(BOOT,30)} rain boots`,"they keep your feet dry in the mud"],[`${ic(BOOK,30)} a garden notebook`,"to write down what came up"],[`${F.ruler({length:4,px:26})} a ruler`,"to find out how tall the sprout got"]],{caption:"Garden Day Chart"})}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const STOPS=[{id:1,title:"Spring Sound Check",short:"Sounds",parts:[{std:["RF.1.2"],n:6,dur:70,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)} ${seedSvg(96)}</p><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend these sounds: /s/ /ee/ /d/ (seed)","Blend these sounds: /s/ /p/ /r/ /ou/ /t/ (sprout)","Clap the word parts in garden. How many parts? (2 parts: gar and den)","What is the last sound in bud? (/d/)","Say all the sounds in rain. (/r/ /ai/ /n/, three sounds)","Which word has a long vowel sound: rain or ran? (rain)"],desc:"blending, segmenting, and isolating sounds, counting syllables, and telling long from short vowels in spoken words"}]},{id:2,title:"Seed Packet Words",short:"Seed Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:85,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. frean is a silly word: listen for the long e that the ea team makes.","Watch for: ch digraph plus ck ending (chick), nd ending (pond), bl blend plus a vowel team (bloom), double letters (well), final e (vine), igh (right), three-letter blend spr plus the ou diphthong (sprout), r-controlled ar (barn), the -ed ending said as /id/ (planted), a compound word (sunshine), two syllables with r-controlled ar (garden)."],desc:"reading words with digraphs, blends, final e, vowel teams, r-controlled vowels, endings, and two syllables"}]},{id:3,title:"Count the Seeds",short:"To 120",parts:[{std:["1.NBT.A.1"],n:4,dur:85,dir:"Count and read out loud. Write your numbers on your paper and hold it up.",html:()=>`<p class="small" style="text-align:center">The class counts every seed before it goes into the row.</p>`,qs:["Count out loud from 94 to 110.","Read these numbers out loud: 73, 102, 118.","Write the number one hundred fifteen.","Count the seeds in the picture. Write the number that tells how many."],fig2:()=>F.row(seedGrid(18,9)),key:["94, 95, 96 ... 99, 100, 101 ... 110. Watch the jump past 99","Seventy-three, one hundred two, one hundred eighteen","115, not 10015","18"],desc:"counting, reading, and writing numerals to 120 and counting objects"}]},{id:4,title:"The First Row",short:"Row Read",parts:[{std:["RF.1.4"],kind:"read",n:76,label:"words read correctly",dur:90,dir:"Look at the three pictures. Then read the story out loud in your best reading voice.",html:()=>`${F.row(F.pic(seedSvg(52),"a bean seed","3.6rem"),F.pic(RAIN,"the rain all night","3.6rem"),F.pic(SPROUT,"the sprout in the row","3.6rem"))}${story("The First Row",FIRST_ROW)}`,key:["76 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Point to the three pictures first so seed, rain, and sprout are clear before the student reads.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: What will the writer do tomorrow? (measure the sprout with a string)"],desc:"a 76-word spring garden story read aloud"}]},{id:5,title:"Garden Problems",short:"Problems",parts:[{std:["1.OA.A.1"],dur:120,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",html:()=>`<div class="figure">${rowFig(7)}</div><p class="small" style="text-align:center">The class plants its seeds in long rows.</p>`,qs:["One tray holds 8 seeds and another tray holds 9. How many seeds in all?","There were 15 sprouts in the tray. 6 of them were moved out to the big bed. How many sprouts are still in the tray?","Lena counted 7 bees on the flowers on Monday. On Friday she counted 16. How many more bees did she count on Friday?","There are 18 pots on the shelf. 9 of them hold beans. The rest hold peas. How many hold peas?","Some seeds were already in the row. Then 5 more went in. Now there are 13. How many were in the row at the start? Write a number sentence with a box and hold it up."],key:["17 seeds (8 + 9 = 17)","9 sprouts (15 - 6 = 9)","9 more bees (16 - 7 = 9 or 7 + 9 = 16)","9 pots of peas (18 - 9 = 9)","8 seeds. Writes a box plus 5 equals 13, or 13 - 5 equals a box"],desc:"addition and subtraction word problems within 20, with the unknown in different places"}]},{id:6,title:"Mina's Seed",short:"Mina",parts:[{std:["RL.1.1"],dur:85,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("Mina's Seed",MINA),qs:["What did Mina find at the bottom of the packet?","Why did she use a cup instead of the garden rows?","Where did she put the cup?","What did she do for it every day?","Ask me a question about the story."],key:["One last seed, down at the bottom","Because there was no room left: every row outside was full already","On the windowsill, in an old cup of soil","Gave it a spoonful of water, every single day","Asks a real question about the story, such as: How long did she wait? If stuck, say: Start with who, what, where, or why."],desc:"asking and answering key detail questions about a story the student read"}]},{id:7,title:"Trays of Ten",short:"Tens Ones",parts:[{std:["1.NBT.B.2"],n:5,dur:90,dir:"Look at the blocks. Answer out loud.",html:()=>`<p class="small" style="text-align:center">A full tray holds 10 seeds. A long block stands for one full tray of ten, and a small cube stands for one loose seed.</p>`,fig:()=>F.row(F.tens(4,6)),qs:["Look at the picture. How many full trays of ten do you see, and how many loose seeds? What number is that?","In the number 28, what does the 2 stand for? What does the 8 stand for?","The shed has 70 seeds. How many full trays of ten is that? How many loose seeds are left over?","Which is more, 5 trays of ten or 40 seeds? How do you know?","The number 12 is one ten and two ones. Say a number that is one ten and seven ones."],key:["4 trays of ten and 6 loose. That is 46","The 2 stands for two tens, which is twenty seeds. The 8 stands for eight ones","7 trays of ten, and 0 loose seeds left over","5 trays of ten. 5 tens is 50, and 50 is more than 40","17"],desc:"place value in two-digit numbers (bundles of ten and leftover ones)"}]},{id:8,title:"Add Up the Garden",short:"Add Up",parts:[{std:["1.NBT.C.4"],n:5,dur:90,dir:"Solve each one on your paper. Say your answer and tell how you got it.",html:()=>`<p class="big" style="margin-top:0">The class counts the garden row by row.</p>`,qs:["Row A has 24 sprouts. 5 more come up. How many now?","Row B has 43 sprouts. The class plants 30 more. How many now?","Row C has 38 seeds in it. 7 more seeds go in. How many now?","Row D has 51 seeds in it. 20 more go in. How many now?","The greenhouse has 67 pots. 8 more pots arrive. How many now?"],key:["29 (24 + 5 = 29. Only the ones change)","73 (43 + 30 = 73. Adding tens to tens: 4 tens and 3 tens is 7 tens)","45 (38 + 7 = 45. 8 + 7 is 15, so a new ten is made)","71 (51 + 20 = 71)","75 (67 + 8 = 75. 7 + 8 is 15, so a new ten is made)"],desc:"adding within 100 (a two-digit number plus a one-digit number and plus a multiple of ten)"}]},{id:9,title:"Take Away Tens",short:"Take Tens",parts:[{std:["1.NBT.C.6"],n:5,dur:75,dir:"Answer out loud. For the last one, tell how you know.",html:()=>`<p class="big" style="margin-top:0">Every tray that gets planted takes ten seeds off the shelf.</p>`,fig:()=>F.row(F.tens(8,0)),qs:["There are 80 seeds on the shelf. Three trays of ten get planted. 80 - 30 is what?","60 - 40","90 - 20","70 - 50","40 - 10. Tell me how you know, using the word tens."],key:["50 (8 tens take away 3 tens is 5 tens)","20","70","20","30. Looks for: 4 tens take away 1 ten is 3 tens, which is 30"],desc:"subtracting multiples of ten from multiples of ten within 100"}]},{id:10,title:"Measure the Vine",short:"Measure",parts:[{std:["1.MD.A.2"],n:5,dur:90,dir:"Look at the blocks under the vine and the hose. Answer out loud.",fig:()=>F.row(unitFig()),qs:["How many blocks long is the vine?","How many blocks long is the hose?","Which is longer, the vine or the hose? How many blocks longer?","Why do the blocks have to touch, with no gaps and no overlaps?","If you measured the vine with blocks that were twice as long, would you need more blocks or fewer blocks?"],key:["6 blocks","4 blocks","The vine. It is 2 blocks longer (6 - 4 = 2)","A gap or an overlap would make the count wrong. The blocks have to sit end to end so each one covers its own part of the length","Fewer blocks. Bigger units means it takes fewer of them to cover the same length"],desc:"measuring length as a whole number of same-size units laid end to end"}]},{id:11,title:"What a Seed Needs",short:"Seed Facts",parts:[{std:["RI.1.1"],dur:85,dir:"Read the facts out loud. Then listen to each question and answer out loud.",html:()=>story("What a Seed Needs",NEEDS),qs:["What three things does a seed need?","What does the water do to the hard coat?","Why should good soil never be packed down too tight?","What is the first part of the plant to come out?","Ask me a question about seeds."],key:["Water, air, and warmth","It softens the coat","So that air can get through to the seed","A small white root, and it pushes down","Asks a real question about the topic, such as: How long does a seed wait? If stuck, say: Start with what, why, or how."],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:12,title:"Garden Sign Check",short:"Signs",parts:[{title:"Sentence Spotter",std:["RF.1.1"],dur:50,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">The seeds are up. Can you see them?</p>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the second sentence. What kind of letter does it start with?","What is the mark at the end of the second sentence called? What does it tell you?","Spot the mistake. Look at the words in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the rain is here</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","The word is Can. It starts with a capital, or uppercase, C","A question mark. It tells you the sentence asks something","The first word needs a capital letter, and the sentence needs a period at the end"],desc:"finding sentences by their first word, capital letter, and end mark"},{title:"Garden Fix It",std:["L.1.1"],dur:70,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Today we water the row. Last week we ____.","One bush, two ____.","Which sounds right? The bee buzz by the flower. Or: The bee buzzes by the flower.","Join these two sentences with the word <b>and</b>: The sun is warm. The soil is wet.","Add a word that tells more about the sprout: The ____ sprout stands in the row.","Finish it so it tells where: The snail sits ____ the leaf."],key:["watered","bushes","The second one. One bee goes with the verb buzzes","The sun is warm, and the soil is wet","Any describing word that fits, such as green, tiny, new, or tall","Any word that tells where and fits, such as under, on, by, or near"],desc:"spoken grammar items (past tense, plural nouns, subject and verb match, joining two sentences, describing words, place words)"}]},{id:13,title:"Rain Radio",short:"Listen",parts:[{title:"Listen Up",std:["SL.1.2"],n:5,dur:65,sup:true,read:WORMS,dir:"Listen carefully. Your teacher will read about what happens in the garden after it rains. Then answer out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)} ${ic(RAIN,96)}</p><p class="big" style="text-align:center">Listen.</p>`,key:["Ask: What did people think for a long time? (that the worms came up because their tunnels had filled with water)","Ask: How does a worm breathe? (through its skin)","Ask: What is the one thing a worm cannot do underground? (travel far)","Ask: Why is a wet morning the right time for a worm to move? (the whole surface is damp, so a worm can crawl a long way)","Say: Ask me one question about worms. (asks 1 question that is about what was read and starts with a question word, such as: How far can a worm go in one morning?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:55,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about something you can watch growing or changing outside right now.</p><ul class="qlist" style="margin-top:14px"><li>What is it?</li><li>What does it look like?</li><li>How do you feel when you look at it?</li></ul>`,key:["Names the thing and gives 2 or more details about it (SL.1.4)","Gives 2 or more details about what it looks like now, and they stay on this one thing (SL.1.4)","Says how it makes them feel to watch it, in at least 1 complete sentence (SL.1.4)"],desc:"describing a thing with relevant details"}]},{id:14,title:"Garden Day Chart",short:"Chart",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:75,dir:"Look at the chart. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">The class wants to find out how much the bean sprout grew this week. What will they take out to the row? Use the chart.</p>`,fig:()=>gardenChart(),key:["Finds the answer in the chart. Your help is fine: read the two columns out loud and point to the row headings","Writes a sentence drawn from the chart, such as: They will take the ruler","The answer fits the question. It names the one thing on the list that is for finding out how tall something got"],desc:"using a provided chart to answer a question in writing"}]},{id:15,title:"Spring Journal",short:"Write",parts:[{wk:"facts",alt:{group:"write",label:"Spring Facts",icon:"📖",hint:"Name it and write some facts"},std:["W.1.2"],n:4,label:"checks met",dur:165,dir:WDIR,html:()=>`<p class="big">Pick one spring thing: a seed, the rain, or a bird. Write its name. Then write 2 or 3 true facts about it. End with one last sentence that wraps it up.</p><div class="figure">${F.pic(seedSvg(52),"a seed","3.6rem")}${F.pic(RAIN,"the rain","3.4rem")}${F.pic(BIRD,"a bird","3.4rem")}</div>${TWO}`,key:["Names the topic: the seed, the rain, or the bird (W.1.2)","Supplies at least 2 facts about it, such as: A seed needs water. A bird builds a nest out of grass (W.1.2)","The facts are about the topic named, not about something else (W.1.2)","Gives some sense of closure, such as: That is how a seed starts (W.1.2)"],desc:"an informative piece about a spring thing, with facts and a closing"},{wk:"story",alt:{group:"write",label:"A Rainy Day",icon:"✏",hint:"Tell two things that happened, in order"},std:["W.1.3"],n:4,label:"checks met",dur:165,dir:WDIR,html:()=>`<p class="big">Write about a day you were out in the rain, or a day you helped something grow. Tell two things that happened, in order. Use the words first and then. End by telling how it felt.</p><div class="figure">${F.pic(BOOT,"out in the rain","3.4rem")}${F.pic(UMBRELLA,"what you took","3.4rem")}${F.pic(SPROUT,"what grew","3.4rem")}</div>${TWO}`,key:["Tells about two or more things that happened, in an order that makes sense (W.1.3)","Includes some detail about what happened, not just a list (W.1.3)","Uses a time word such as first, then, next, or after that to signal the order (W.1.3)","Ends with a sense of closure, such as how it felt or what happened last (W.1.3)"],desc:"a narrative about a rainy day or a day the student helped something grow, told in order"}]},{id:16,title:"Turn It Around",short:"Turn It",parts:[{std:["1.OA.B.3"],n:3,dur:75,dir:"Look at the two frames. Answer out loud.",fig:()=>F.row(F.label(F.tenFrame(8),"8 bean seeds"),F.label(F.tenFrame(6),"6 pea seeds")),qs:["9 + 4 = 13. What is 4 + 9? How do you know that without adding it again?","Now use the frames. Move 2 of the pea seeds into the 2 empty boxes of the bean frame. What two numbers are you adding now, and what is 8 + 6?","Add 4 + 6 + 7. Which two would you put together first, and why?"],key:["13. Turning the two numbers around does not change the total, so 4 + 9 has to be 13 too. Count it correct only when the student says the order does not matter, not just the answer","10 and 4, which is 14. So 8 + 6 = 14. The bean frame fills to 10 and 4 pea seeds are left over","4 and 6 first, because they make a ten. Then 10 + 7 = 17. Adding 6 + 7 first and then 4 gets 17 as well, but the point here is choosing the pair that makes a ten"],desc:"using the order of addends and making a ten as strategies to add"}]},{id:17,title:"Count On, Count Back",short:"Count On",parts:[{std:["1.OA.C.5"],n:3,dur:65,dir:"Use the number line. Answer out loud.",fig:()=>F.row(F.numberLine({min:0,max:20,width:680})),qs:["Start at 12 and count on 3. Where do you land? What addition fact did you just do?","Start at 16 and count back 4. Where do you land? What subtraction fact is that?","To work out 9 + 2, would you count on from 9 or count on from 2? Why?"],key:["15. The fact is 12 + 3 = 15","12. The fact is 16 - 4 = 12","Count on from 9: 10, 11. Starting at the bigger number means only 2 counts instead of 9. Starting at 2 and counting on 9 works too, but it takes far longer"],desc:"counting on to add and counting back to subtract, and naming the matching fact"}]},{id:18,title:"Garden Clocks",short:"Clocks",parts:[{std:["1.MD.B.3"],n:3,dur:65,dir:"Look at the two clocks. Answer out loud. Then write one time on your paper.",fig:()=>F.row(F.label(F.clock(4,0),"Clock A"),F.label(F.clock(7,30),"Clock B")),qs:["What time does Clock A show? How do you know?","What time does Clock B show? How do you know?","Write the Clock B time on your paper the way a digital clock would show it."],key:["4 o'clock, or 4:00. The short hand is on the 4 and the long hand is straight up on the 12","Half past 7, or 7:30. The long hand points straight down at the 6, and the short hand sits halfway between the 7 and the 8","7:30. Accept any clear writing of it. Watch for 7:6 or 6:30, which both mean the student read the long hand as a number instead of as 30 minutes"],desc:"telling and writing time to the hour and the half hour on an analog clock"}]},{id:19,title:"Seedling Chart",short:"Seedlings",parts:[{std:["1.MD.C.4"],n:3,dur:70,dir:"Look at the chart. Answer out loud.",fig:()=>F.row(F.barGraph({cats:["beans","peas","carrots"],vals:[8,5,3],max:10,step:1,title:"Seedlings up this week"})),qs:["How many seedlings came up in all?","How many more bean seedlings are there than carrot seedlings?","Which kind has the fewest? How many fewer is that than the peas?"],key:["16. 8 + 5 + 3 = 16","5 more. 8 - 3 = 5","Carrots, with 3. That is 2 fewer than the peas (5 - 3 = 2)"],desc:"reading a three-category chart for the total, for one category, and for how many more or fewer"}]},{id:20,title:"Share the Beds",short:"Shares",parts:[{std:["1.G.A.3"],n:3,dur:70,dir:"Look at the round tray and the long bed. Answer out loud.",fig:()=>F.row(F.label(F.fracCircle(2,1,170),"round tray, cut into 2 equal shares"),F.label(F.gridRect(1,4,1,{cell:62}),"long bed, cut into 4 equal shares")),qs:["The round tray is cut into 2 equal shares. What is each share called, and how much of the tray is shaded?","The long bed is cut into 4 equal shares. What are those called, how much is shaded, and how many of them make the whole bed?","Suppose you cut the round tray into 4 equal shares instead of 2. Does each share get bigger or smaller? Why?"],key:["Halves. One half of the tray is shaded, which is 1 of the 2 equal shares","Fourths, or quarters. One fourth of the bed is shaded, which is a quarter of it. Four fourths make the whole bed","Smaller. The same tray has to go into more shares, so each share gets a smaller piece of it"],desc:"naming halves and fourths, telling how many shares make the whole, and knowing more shares means smaller shares"}]},{id:21,title:"The Best Part of Spring",short:"Opinion",parts:[{wk:"opinion",std:["W.1.1"],n:4,label:"checks met",dur:90,dir:WDIR,html:()=>`<p class="big">What is the best part of spring in the garden: the rain, the first sprout, or the flowers? Name the one you pick. Write what you think. Give one reason. Then write one last sentence to finish it off.</p><div class="figure">${F.pic(RAIN,"the rain","3.4rem")}${F.pic(SPROUT,"the first sprout","3.4rem")}${F.pic(FLOWER,"the flowers","3.4rem")}</div>${TWO}`,key:["Names the topic, which one of the three the writing is about (W.1.1)","States an opinion about it, such as: The rain is the best part of spring (W.1.1)","Supplies a reason for the opinion, such as: because it fills the puddles, or because it means the seeds will come up (W.1.1)","Gives some sense of closure, a last sentence that finishes it off rather than stopping mid-thought (W.1.1)"],desc:"an opinion piece about the best part of spring, with a topic, an opinion, a reason, and a closing"}]},{id:22,title:"Copy a Maple Seed",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job a plant part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A maple seed has a wing. The wing is flat and papery. It is on one side. It comes off the tree. The wing makes it spin. The spin holds it in the air. It stays up long enough. Then the wind can carry it. It goes far from the parent tree.</p>
     <div class="figure">${ic("maple",96)}${ic("wind",88)}</div>
     <p class="big">The gardener has light seed. She wants it to land spread out. It should go across a wide bed. But she throws every handful. It drops in one heavy clump.</p>`,qs:["How does a flat papery wing get a maple seed further away from its parent tree?","Draw something the gardener could drop her seed in that copies the maple seed's wing.","Tell me which plant part you copied and how it spreads the seed out instead of dropping it in a clump."],key:["The wing makes the seed spin, the spin keeps it up in the air longer, and while it is up there the wind carries it sideways. Any answer about staying up longer or catching the wind counts.","Any design that catches air: a paper wing or blade on each seed packet, a spinner, a little parachute, a wide flat scoop the wind can take the seed off, a fan to blow it out.","Needs both halves: names the flat papery wing as the part copied, and says catching the air slows the fall so the seed drifts apart instead of dropping straight down together."]}]},{id:23,title:"Robin Parents",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"A robin has built a nest in the hedge at the end of the field. All day long one of the parents flies off and comes back with a worm. Every single time a parent lands on the rim, the three young throw their heads back and open their beaks as wide as they will go, and the parent drops the worm into whichever beak is highest. When the young are bigger the parent stops landing on the rim. It stands on the grass below and pulls a worm up while they watch, and after a few days the young start pulling at the grass themselves.",qs:["What do the young robins do every single time a parent lands on the rim of the nest?","What does the parent do differently once the young are bigger?","How does watching the parent pull a worm out of the grass help a young robin later on?"],key:["They throw their heads back and open their beaks as wide as they can. Every single time is what makes it a pattern.","It stops landing on the rim and pulls worms up on the grass below where the young can watch.","The young learn how to find their own food by copying what the parent does, so they can feed themselves once they leave the nest."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">Three seedlings came up. They came from one packet of seeds. All were saved from the same plant. It was the parent plant. A puppy and a dog. The dog is its parent.</p>
     <div class="figure">${ic("sprout",80)}${ic("sprout",96)}${ic("sprout",68)}</div>
     <div class="figure">${ic("dog",88)}${ic("dog",116)}</div>`,qs:["The three seedlings came from the same parent plant but they are not the same height. Does that mean one of them is a different kind of plant? Say why.","Name one way all three seedlings are like the parent plant they came from.","The puppy has the same shape of ears, nose and tail as the parent, but it is smaller and its coat is a different color. Is the puppy the parent's young? Say how you can tell."],key:["No. Plants grown from one parent are like it and like each other, but not exactly the same. Being a different height is one of those differences.","Same kind of leaf, same green color, same shape of stem, all come out of the ground the same way. Any likeness counts.","Yes. Young are like their parents in the big ways, the shape of the ears and nose and tail, and different in smaller ways like size and color."]}]},{id:24,title:"Earlier Every Week",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">The gardener wrote down the time the sun came up, once a week for four weeks.</p>
     <table class="bigTable"><tr><th>Week</th><th>Time the sun came up</th></tr>
     <tr><td>first week</td><td>6:50</td></tr><tr><td>second week</td><td>6:40</td></tr>
     <tr><td>third week</td><td>6:30</td></tr><tr><td>fourth week</td><td>6:20</td></tr></table>
     <div class="figure">${ic("sun",84)}${ic("sprout",84)}${ic("cloud",84)}</div>`,qs:["Is the sun coming up earlier or later as the weeks go by?","How many minutes earlier does it come up each week?","What time do you predict the sun will come up in the fifth week, and how do you know?","The sun has come up over the same hedge every one of those mornings. Is where it comes up a pattern too?"],key:["earlier each week","10 minutes earlier each week","6:10. The times go down by 10 minutes every week, and a pattern that repeats lets you predict the next one.","Yes. It has come up in the same place every morning, so where it rises can be predicted as well as when."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">Hours of daylight on the first day of three spring months.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th></tr>
     <tr><td>March</td><td>12</td></tr><tr><td>April</td><td>13</td></tr>
     <tr><td>May</td><td>14</td></tr></table>`,qs:["Are the hours of daylight going up or down as spring goes on?","How many more hours of daylight does May have than March?","Seedlings need light to grow. Using the chart, say whether a seedling planted in May gets more light in a day than one planted in March."],key:["going up, one hour more each month","2 more hours. 14 take away 12","Yes, more. May has 14 hours of daylight in a day and March has 12, so a May seedling gets two more hours of light each day."]}]},{id:25,title:"A Blade of Grass",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you can find a wide blade of grass, try the first part. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Hold a wide blade of grass tight between your two thumbs and blow hard across the edge of it.</p>
     <div class="figure">${ic("herb",96)}${ic("milk",96)}</div>
     <p class="big">Now stretch plastic wrap over the top of a jar and tape it down. Put one seed on top and sing a loud note right next to it.</p>`,qs:["What has to happen to the blade of grass before you hear the squeak?","Let one thumb go slack so the grass is loose. What happens to the sound, and why?","What does the seed on the plastic wrap do while you sing?","You never touched the seed. Say what moved it, and how."],key:["It has to shake. The air rushing past the edge makes the blade shake very fast, and the shaking makes the sound.","The sound stops or goes dull. A loose blade cannot shake the same way, and no shaking means no sound.","It hops, jiggles, or rolls about.","Your singing shook the air, the shaking air made the plastic wrap shake, and the shaking wrap moved the seed. A sound can move a thing without touching it."]}]},{id:26,title:"The Dark Potting Shed",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The potting shed has one small window. A heavy cover goes over it. The cover is down. The door is shut. No light gets in at all.</p>
     <div class="figure">${ic("box",96)}${ic("torch",96)}</div>`,qs:["A packet of seeds is on the bench inside the dark shed. Can you see it? Say why or why not.","What would have to get into that shed before you could see the packet?","A bright yellow glove is on the same bench. Someone says yellow glows in the dark. Is that true for an ordinary yellow glove? Say why."],key:["No. No light gets into the shed, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: a flashlight, a lamp, the door opened, or the window cover lifted.","No. An ordinary yellow glove only looks bright because it bounces back a lot of light. With no light at all it cannot be seen either."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">One flashlight beam was pointed at four things in the shed and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a glass jar over a seedling</td><td>went straight through</td></tr>
     <tr><td>a thin cloth row cover</td><td>a dim light came through</td></tr>
     <tr><td>a wooden plank</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>the shiny side of a watering can</td><td>bounced off in a new direction</td></tr></table>`,qs:["Which thing let all the light through?","Which thing let a little light through?","Gardeners lay thin cloth over young plants on cold nights. Using the chart, say whether the plants under it still get some light.","Which of the four would you put over a seedling that needs as much light as it can get, and why?"],key:["the glass jar","the thin cloth row cover","Yes, some. The chart says a dim light came through the cloth, so the plants under it get a little but not all of it.","the glass jar, because the chart shows the beam went straight through it, so the seedling keeps nearly all the light."]}]},{id:27,title:"Across the Field",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The far end of the field is a long walk from the house, and a shout does not carry that far over open ground.</p>
     <div class="figure">${ic("tractor",88)}${ic("megaphone",88)}${ic("lamp",88)}</div>`,qs:["Draw a device at the house that tells the person at the far end of the field that it is time to come in. It has to use light or sound.","Explain what you drew and say which of the two, light or sound, it uses.","Rain is pouring down and the field is loud with it. Would your device still get the message through? Say what you would do about it."],key:["Any device that carries light or sound across the field: a bell, a horn, a whistle, a drum, a bright lamp on a pole, a lamp flashed on and off.","Names it and says which one it uses.","A sound may be drowned out by heavy rain, so a bright light would carry better. A student who argues for a very loud bell and explains why is reasoning well, so take the reasoning."]}]},{id:28,title:"Fix the Falling Seedlings",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"The bean seedlings in the end row have grown tall and thin. Every time the wind comes across the open field, some of them bend right over and lie flat on the soil. A seedling that spends a day lying on wet soil does not do well afterwards.",qs:["What is the problem the gardener wants to change?","What is one question you would ask the gardener before you built anything?","Before building a support, what would you go out and measure?"],key:["Tall thin seedlings bend over in the wind and lie flat on the soil.","Any real question: how tall are they, how strong is the wind, which way does it come from, how many fall, is the end row worse than the others. A statement is not a question, so ask once more.","Any real observation: count how many bend over, measure how tall they are, note which direction the wind comes from, see whether the middle rows fall too."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw something that keeps the tall seedlings standing up in the wind.</p>
     <div class="figure">${ic("sprout",88)}${ic("ruler",88)}${ic("box",88)}</div>`,qs:["Draw your fix on the row of seedlings.","Point to the part that holds the stem up and tell me its shape.","Tell me why that shape holds better than piling a little extra soil round the bottom."],key:["Any real fix: a stick beside each stem with a loose tie, a low fence along the row, a wind break at the end of the row, a cage round each plant, a string between two posts the plants lean on.","Names a shape: a straight upright stick, a ring round the stem, a long low wall, a flat panel standing on its edge.","Because the shape holds the stem up along its length or blocks the wind before it arrives. Extra soil only holds the very bottom, and a tall thin stem bends above it."]}]},{id:29,title:"Which Support Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two supports were tried on the same windy day, fifteen seedlings with each.</p>
     <table class="bigTable"><tr><th>Support</th><th>Seedlings that bent over, out of 15</th></tr>
     <tr><td>a stick and a loose tie</td><td>2</td></tr>
     <tr><td>extra soil round the bottom</td><td>10</td></tr></table>`,qs:["Which support worked better in the test?","Point to the numbers that show it and tell me what they are.","Someone says the extra soil is better because it costs nothing. Does costing nothing make it better at holding seedlings up? Say why or why not."],key:["the stick and the loose tie","Only 2 seedlings out of 15 bent over with the stick, and 10 out of 15 bent over with the extra soil. The numbers have to be in the answer.","No. Costing nothing is a different question from working. The test counted seedlings that bent over, and the stick kept far more of them standing."]}]},{id:30,title:"The Town Library",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and explaining why a shared service has rules",read:"Anybody who lives in the town may get a library card, and a card costs nothing. With a card you may take four books home at a time. The books belong to the whole town, so they have to come back in three weeks, and they have to come back in the state they left in. If a book is late the library sends a note asking for it, because somebody else is waiting.",qs:["Anybody who lives in the town may get a card. Is that a right or a responsibility?","Bringing the books back in three weeks is something you must do. Is that a right or a responsibility?","The books belong to the whole town. Why does that make returning them on time matter to people you have never met?","Name one other place in a town that belongs to everybody, and one rule that keeps it good for everybody."],key:["a right","a responsibility","Because somebody else is waiting for that book. A thing everybody shares only works if each person gives it back for the next one.","Any real pair: the park and not dropping litter, the pool and following the guard's rules, the bus and paying the fare, the sidewalk and keeping it clear."]}]},{id:31,title:"The Field Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the farm field, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("cabin",56)}</td><td></td><td>${ic("tree",56)}</td></tr>
     <tr><th>B</th><td>${ic("sprout",56)}</td><td>${ic("sprout",56)}</td><td>${ic("sprout",56)}</td></tr>
     <tr><th>C</th><td></td><td>${ic("drop",56)}</td><td>${ic("bridge",56)}</td></tr></table>
     <p class="big">${ic("cabin",48)} the farmhouse &nbsp; ${ic("tree",48)} the hedge &nbsp; ${ic("sprout",48)} the seedling rows &nbsp; ${ic("drop",48)} the stream &nbsp; ${ic("bridge",48)} the plank bridge</p>`,qs:["Find the farmhouse. Give its exact spot on the grid, the letter and the number.","Where is the stream compared to the farmhouse? Use words like above, below, left of, or right of.","Name the things on this map that grew or flowed there on their own.","Someone walks from the farmhouse to the plank bridge, moving one square at a time. Name the squares they could cross."],key:["A1. Both parts are needed.","Below the farmhouse and to the right of it. Down and over counts too.","The hedge and the stream.","Any sensible square by square path, for example A1 to B1 to C1 to C2 to C3, or A1 to B2 to C3. The point is moving square by square rather than leaping across."]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">On market day there are fourteen stalls. They line the main street. People are running them. They grew up in nine different places. Three of the stalls sell food. Nobody in the town had tasted it. That was twenty years ago.</p>
     <p class="big">California was the homeland of nations. They were American Indian nations. That was long before. No town was built here yet. Many place names here came from them. Our names come from their languages. Since then immigrants have come. They are people who moved here. They came from other countries. They brought the foods and the words. They brought the music and the work. They make the state what it is.</p>
     <div class="figure">${ic("bread",88)}${ic("cheese",88)}${ic("carrot",88)}</div>`,qs:["Do all the people running stalls on one street come from the same place? Say how you know.","Name three things people built in your own town, and say what one of them does for the people there.","Two groups of people helped make California what it is: the American Indian nations who were here first, and the immigrants who came from other countries. Name one thing each group gave to this state."],key:["No. They grew up in nine different places.","Any three built things with a use for one: a school teaches children, a hospital takes care of people, a road lets people travel, a store sells things, a library lends books.","American Indian nations: the names of many places, the first paths and trails, knowing which plants and animals belong here, basket weaving and other crafts, and nations that are still here today. Immigrants: foods, words, music, farming and other work, shops and businesses, holidays their families keep. One from each group is what is being checked. (HSS-1.5)"]}]},{id:32,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what a national memorial is for and naming a tradition people keep over many years",html:()=>`<p class="big">Washington, D.C. has a long building. It is white marble. It has wide steps. Inside is a huge stone statue. It is Abraham Lincoln. He is sitting in a chair. It is called the Lincoln Memorial. People have come to stand there. Those steps have held them. They have come for many years. It is more than a hundred.</p>
     <div class="figure">${ic("flag",96)}${ic("star",96)}</div>`,qs:["Who is the statue inside the Lincoln Memorial?","A memorial is built to remember somebody. Why would a whole country build one instead of just writing the person's name down somewhere?","People have come to those steps for more than a hundred years. What do you call something people keep doing year after year like that?"],key:["Abraham Lincoln, a president of the United States.","Because a big building that people can visit together keeps the memory alive for everybody, not just for the people who read one page. Any answer about remembering together counts.","A tradition. Accept a custom. If the student cannot name it, ask what they call the things their own family does every year."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Getting a field ready for planting.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>what pulled the plow</td><td>two horses in harness</td><td>a tractor with an engine</td></tr>
     <tr><td>how long one field took</td><td>three days</td><td>two hours</td></tr>
     <tr><td>why it was done</td><td>to break up the soil for seed</td><td>to break up the soil for seed</td></tr></table>
     <div class="figure">${ic("horse",88)}${ic("tractor",88)}</div>`,qs:["Long ago, what pulled the plow across a field?","What pulls it today?","Point to a row where long ago and today do not match. Tell me what is different in that row.","Tell me one thing people still do for the very same reason they did long ago."],key:["Two horses in harness.","A tractor with an engine.","What pulled the plow changed, or how long a field took changed. Either counts.","Why it was done: to break up the soil so seed can go in. That is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["springtime","unplanted","greenest"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["springtime (two syllables, compound word, the spr blend)","unplanted (prefix un- and the -ed ending said as /id/)","greenest (suffix -est on a word with the ee team)"]},4:{id:"L4",lv:true,title:"Level Up: The Greenhouse",std:["RF.2.4"],needs:["RF.1.4"],n:62,label:"words read correctly",dir:"Read this harder story out loud in your best reading voice.",html:()=>`<p class="passage">${GREENHOUSE}</p>`,key:["62 words. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace and expression. A grade 2 reader should group the words into phrases, not read one word at a time.","Quick check after reading: Why does the glass roof help? (the sunlight gets in but the wind stays out)"]},5:{id:"L5",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The shed had 36 seed packets. A box of 27 more came in. Then the class used 19 of them on planting day. How many seed packets are left in the shed?</p>`,key:["44 packets (36 + 27 = 63, then 63 - 19 = 44)"]},6:{id:"L6",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${MINA}</p><ol class="qlist"><li>Why did Mina plant her seed in a cup?</li><li>How do you know Mina had to wait a long time?</li></ol>`,key:["Because the garden rows were already full, so there was no room left for one more seed","The story says she watered it every day and that for a long time nothing happened at all"]},8:{id:"L8",lv:true,title:"Level Up: Add It Both Ways",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:3,dir:"Solve each one on your paper. Show your work and hold it up.",html:()=>`<ol class="qlist"><li>38 + 46</li><li>72 - 35</li><li>57 + 29</li></ol>`,key:["84 (38 + 46 = 84)","37 (72 - 35 = 37)","86 (57 + 29 = 86)"]},11:{id:"L11",lv:true,title:"Level Up: Prove It",std:["RI.2.1"],needs:["RI.1.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.5rem">${NEEDS}</p><ol class="qlist"><li>Why is a seed called a tiny plant with its own lunch packed around it?</li><li>How do you know a seed can sit for a long time without changing?</li></ol>`,key:["Because the food the little plant needs to start is already stored inside the seed with it. Reads the first line.","Reads the line that says the seed stays dry and still until three things reach it. Nothing happens until water, air, and warmth arrive."]}};const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","RI.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={facts:["A ____ is ____.","One thing about it is ____.","It also ____.","That is how ____."],story:["One day, ____.","First, ____.","Then, ____.","It felt ____."],opinion:["The best part of spring is ____.","I think ____.","I think so because ____.","That is why ____."]};function sentHtml(st){const wk=st&&st.parts&&st.parts[0]&&st.parts[0].wk||"facts";return`<ul class="starters">${(STARTERS[wk]||STARTERS.facts).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsBlk=[0,0];function tpsBlkHtml(){return`<div class="blk-row"><button class="chip" data-tb="0" data-td="1">Add a ten</button><button class="chip" data-tb="0" data-td="-1">Take a ten</button><button class="chip" data-tb="1" data-td="1">Add a one</button><button class="chip" data-tb="1" data-td="-1">Take a one</button><button class="chip" data-tb="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]?F.tens(tpsBlk[0],tpsBlk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} tens and ${tpsBlk[1]} ones on the mat.</p>`}function tpsBlkBind(b,r){b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{if(x.dataset.tb==="x")tpsBlk=[0,0];else{const i=+x.dataset.tb;tpsBlk[i]=Math.max(0,Math.min(i?19:9,tpsBlk[i]+ +x.dataset.td))}r()})}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:tpsBlkHtml,bind:tpsBlkBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.A.1"],msg:"With the number line the student can count every hop to an answer. Note whether the answer came from counting or from knowing the fact."},{t:"nl",std:["1.MD.A.2"],msg:"The number line is itself a line of same-size units. If it was open during the measuring stop, note that the unit idea was in front of the student."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows the numerals, so counting, reading, and writing numbers with it open is supported, not independent."},{t:"chart",std:["1.NBT.C.4","1.NBT.C.6"],msg:"On the 120 chart a student can hop down a column to add or take away a ten. Note whether the answer came from the chart or from knowing the tens."},{t:"tf",std:["1.NBT.B.2"],msg:"Ten frames show the bundles of ten for the student. Note it if the tens and ones were read off the frames rather than said from the number."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.2","W.1.3","W.1.8"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"nl",std:["1.OA.C.5"],msg:"The number line is the model this stop asks about, so using it is the task, not a support. Note only whether the student needed you to point out where to start."},{t:"nl",std:["1.OA.B.3"],msg:"With the number line the student can count the whole way to an answer instead of using the order of the addends or a ten. Note which route the answer came from."},{t:"tf",std:["1.OA.B.3"],msg:"The ten frames show the make-a-ten move. That is what the stop asks for, so it counts, but note whether the student moved the counters alone or you moved them."},{t:"scribe",std:["W.1.1"],msg:"If an adult wrote the opinion for the student, note it. The opinion, reason and closing still count, but the printing does not."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
